{"explanation":"The inscribed angle theorem says an angle with its vertex P on a circle is exactly half of the central angle ∠AOB that cuts off the same arc. So as long as P stays on the same arc, ∠APB doesn't change. Drag the yellow point P around the circle and the readout on the right stays fixed. If you move P onto the short arc between A and B, the angle becomes 180° − θ (the supplement), because P now cuts off the other arc. You can also drag A and B to change the arc, and the inscribed angle is still always half the central angle.","manimCode":"const O = [-2, -0.2, 0];
const R = 2.7;
const pt = (a) => [O[0] + R * Math.cos(a), O[1] + R * Math.sin(a), 0];
const angOf = (p) => Math.atan2(p[1] - O[1], p[0] - O[0]);
const norm = (a) => { while (a <= -Math.PI) a += 2 * Math.PI; while (a > Math.PI) a -= 2 * Math.PI; return a; };
const pos = (a) => { a = a % (2 * Math.PI); return a < 0 ? a + 2 * Math.PI : a; };

const circle = new Circle({ radius: R, color: BLUE_C });
circle.moveTo(O);
const centerDot = new Dot({ point: O, color: WHITE });
scene.add(circle, centerDot);

let aA = 210 * Math.PI / 180, aB = 330 * Math.PI / 180, aP = 100 * Math.PI / 180;

const mkSeg = (col, w) => { const s = new Polygon({ vertices: [[0,0,0],[1,0,0]], color: col }); s.setStrokeWidth(w); s.setFillOpacity(0); return s; };
const NW = 24;
const mkWedge = (col) => { const w = new Polygon({ vertices: Array.from({ length: NW + 1 }, () => [0,0,0]), color: col }); w.setFill(col, 0.35); w.setStrokeWidth(2); return w; };

const pa = mkSeg(YELLOW, 4), pb = mkSeg(YELLOW, 4);
const oa = mkSeg(GREEN, 3), ob = mkSeg(GREEN, 3);
const wedgeP = mkWedge(YELLOW), wedgeO = mkWedge(GREEN);
scene.add(wedgeO, wedgeP, oa, ob, pa, pb);

const dotA = new Dot({ point: pt(aA), color: RED });
const dotB = new Dot({ point: pt(aB), color: RED });
const dotP = new Dot({ point: pt(aP), color: YELLOW });
dotA.scale(1.4); dotB.scale(1.4); dotP.scale(1.8);
scene.add(dotA, dotB, dotP);

const lab = (s, col) => { const t = new Text({ text: s, color: col, fontSize: 30 }); scene.add(t); return t; };
const lA = lab('A', RED), lB = lab('B', RED), lP = lab('P', YELLOW), lO = lab('O', WHITE);
lO.moveTo([O[0] + 0.3, O[1] - 0.3, 0]);

function wedgeVerts(v, a1, d, r) {
  const vs = [[v[0], v[1], 0]];
  for (let i = 0; i < NW; i++) { const a = a1 + d * i / (NW - 1); vs.push([v[0] + r * Math.cos(a), v[1] + r * Math.sin(a), 0]); }
  return vs;
}

let infoGroup = null;
let lastKey = '';
function updateInfo(ins, cen) {
  const key = ins.toFixed(1) + '|' + cen.toFixed(1);
  if (key === lastKey) return;
  lastKey = key;
  if (infoGroup) infoGroup.forEach(t => scene.remove(t));
  const t1 = new Text({ text: 'Inscribed  ∠APB = ' + ins.toFixed(1) + '°', color: YELLOW, fontSize: 28 });
  const t2 = new Text({ text: 'Central  ∠AOB = ' + cen.toFixed(1) + '°', color: GREEN, fontSize: 28 });
  const t3 = new Text({ text: '∠AOB / ∠APB = ' + (ins > 0.01 ? (cen / ins).toFixed(2) : '—'), color: WHITE, fontSize: 28 });
  t1.moveTo([3.7, 1.0, 0]); t2.moveTo([3.7, 0.2, 0]); t3.moveTo([3.7, -0.6, 0]);
  infoGroup = [t1, t2, t3];
  scene.add(t1, t2, t3);
}

const title = new Text({ text: 'Inscribed Angle Theorem', color: WHITE, fontSize: 34 });
title.moveTo([3.7, 2.6, 0]);
const hint = new Text({ text: 'Drag P (or A, B) along the circle', color: GRAY, fontSize: 22 });
hint.moveTo([3.7, -2.4, 0]);
scene.add(title, hint);

function update() {
  const A = pt(aA), B = pt(aB), P = pt(aP);
  dotA.moveTo(A); dotB.moveTo(B); dotP.moveTo(P);
  pa.setVertices([P, A]); pb.setVertices([P, B]);
  oa.setVertices([O, A]); ob.setVertices([O, B]);
  const off = (a) => [O[0] + (R + 0.35) * Math.cos(a), O[1] + (R + 0.35) * Math.sin(a), 0];
  lA.moveTo(off(aA)); lB.moveTo(off(aB)); lP.moveTo(off(aP));

  // inscribed angle at P
  const a1 = Math.atan2(A[1] - P[1], A[0] - P[0]);
  const a2 = Math.atan2(B[1] - P[1], B[0] - P[0]);
  const d = norm(a2 - a1);
  wedgeP.setVertices(wedgeVerts(P, a1, d, 0.6));
  const ins = Math.abs(d) * 180 / Math.PI;

  // central angle on the arc NOT containing P
  const ccwAB = pos(aB - aA);
  const pIn = pos(aP - aA) < ccwAB;
  const dc = pIn ? -(2 * Math.PI - ccwAB) : ccwAB;
  wedgeO.setVertices(wedgeVerts(O, aA, dc, 0.55));
  const cen = Math.abs(dc) * 180 / Math.PI;
  updateInfo(ins, cen);
}
update();

const snap = (which) => (mob) => {
  const a = angOf(mob.getCenter());
  if (which === 'P') aP = a; else if (which === 'A') aA = a; else aB = a;
  update();
};
makeDraggable(dotP, scene, { onDrag: snap('P') });
makeDraggable(dotA, scene, { onDrag: snap('A') });
makeDraggable(dotB, scene, { onDrag: snap('B') });
makeHoverable(dotP, scene, { hoverScale: 1.3 });

const controls = new Controls(scene, { position: 'bottom-right' });
controls.addButton({ label: 'Reset', onClick: () => {
  aA = 210 * Math.PI / 180; aB = 330 * Math.PI / 180; aP = 100 * Math.PI / 180; update();
}});

await scene.wait(999999);"}

